INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118061, 91002, "フリーマーケット会場", "ペコリーヌとの出会い", 2, 1, "青空の下で謁見", "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 20063115, 7, 0, 10118, 8, 2834, 40);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118062, 91002, "フリーマーケット会場", "マホとの出会い", 2, 1, "未来の騎空団\nマスコット？", "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 20063115, 7, 0, 10118, 8, 2835, 40);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118063, 91002, "ランドソル市街地", "アキノとの出会い", 2, 1, "お嬢さまからの\n緊急依頼", "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 20063115, 7, 0, 10118, 8, 2837, 40);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118064, 91002, "フリーマーケット会場", "ジュンとの出会い", 2, 1, "黄金色の悩みごと", "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 20063115, 18, 0, 10118, 8, 4108402, 40);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118065, 91002, "フリーマーケット会場", "カオリとの出会い", 2, 1, "白熱！　格闘大会！", "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 20063115, 18, 0, 10118, 8, 4107402, 40);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118066, 91002, "オーエド町", "ニノンとの出会い", 2, 1, "祭り太鼓はオーエドの華", "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 20063115, 16, 1, 10118, 8, 9000227, 40);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118067, 91002, "フリーマーケット会場", "スズナとの出会い", 3, 1, "人気者は遅れて\nやってくる", "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 20063115, 19, 0, 10118, 8, 2101181, 40);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118068, 91002, "ランドソル市街地", "ナナカとの出会い", 3, 1, "巫女・ミーツ・魔法少女", "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 20063115, 18, 0, 10118, 8, 4109402, 40);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118069, 91002, "フリーマーケット会場", "キャル＆コッコロとの出会い", 3, 1, "ネズ耳は二度なくなる", "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 20063115, 18, 0, 10118, 8, 4305402, 40);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118070, 91002, "ランドソル市街地", "ユカリとの出会い", 3, 1, "この出会いにカンパイ！", "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 20063115, 18, 0, 10118, 8, 4101402, 40);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118071, 91002, "ランドソル市街地", "アオイとの出会い", 3, 1, "陰陽アンサンブル", "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 20063115, 18, 0, 10118, 8, 4106402, 40);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118072, 91002, "フリーマーケット会場", "シノブとの出会い", 3, 1, "運試し十番勝負！", "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 20063115, 7, 1, 10118, 8, 2836, 40);
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118600, 0, 0, "オープニング", 1, 0, "彼女たちの新たな日常", 0, 20063115, 0, 0, 10118, 0, 0, 0);
